#!/usr/bin/env bash
# Generated by gemma4-bench for run 20261015-1436-sgl-n684-fa3fa4-p64-h200-1x02-ci-tau2; the measurement lives in recipes/run_cell.sh.
set -o pipefail
source "$(dirname "$0")/../../benchmark_lib.sh"
check_env_vars CONC PORT INFMAX_CONTAINER_WORKSPACE RESULT_FILENAME
export BENCH_DIR="$INFMAX_CONTAINER_WORKSPACE/bench-20261015-1436-sgl-n684-fa3fa4-p64-h200-1x02-ci-tau2"
rm -rf "$BENCH_DIR"; mkdir -p "$BENCH_DIR/datasets"
cp -r "$INFMAX_CONTAINER_WORKSPACE/benchmarks/gemma4j/20261015-1436-sgl-n684-fa3fa4-p64-h200-1x02-ci-tau2/." "$BENCH_DIR/"
source "$BENCH_DIR/patches/apply_patches.sh" "$BENCH_DIR/patches" "$BENCH_DIR/site" > "$BENCH_DIR/patch-info.txt" || { cat "$BENCH_DIR/patch-info.txt"; exit 1; }
cat "$BENCH_DIR/patch-info.txt"
install_agentic_deps || exit 1
TAU2_DIR=$("$AIPERF_PYTHON" -c "import sys; from huggingface_hub import snapshot_download; print(snapshot_download(sys.argv[1], repo_type='dataset', revision=sys.argv[2] or None))" thangquang09/customer-service-agent-traces "$(sed -n 's/^TAU2_REV=//p' "$BENCH_DIR/run.env" | grep -v '^local$')") || exit 1
T2_DST="$BENCH_DIR/datasets/$(basename "$(sed -n 's/^TAU2_FILE=//p' "$BENCH_DIR/run.env")")"
cp "$(find "$TAU2_DIR" -maxdepth 2 -name '*.jsonl' | head -1)" "$T2_DST"
_want=$(sed -n 's/^TAU2_SHA=//p' "$BENCH_DIR/run.env"); _got=$(sha256sum "$T2_DST" | cut -d' ' -f1)
[ "$_want" = "$_got" ] || { echo "dataset sha256 $_got != recorded TAU2_SHA $_want" >&2; exit 1; }
sed -i "s|/bench/|$BENCH_DIR/|g" "$BENCH_DIR/run.env" "$BENCH_DIR"/launches/*/launch.env
sed -i 's|^EXECUTOR=.*|EXECUTOR=ci|; s|^PORT=.*|PORT='"$PORT"'|' "$BENCH_DIR/run.env"
for f in "$BENCH_DIR"/launches/*/launch.env; do
  if grep -q '^WORKLOAD=tau2$' "$f"; then sed -i 's|^POINTS=.*|POINTS="$CONC:0"|' "$f"; else rm -rf "$(dirname "$f")"; fi
done
bash "$BENCH_DIR/recipes/run_cell.sh"; rc=$?
# one server per CI job: keep this job's log next to its point, so another job's log never stands in for it
for p in "$BENCH_DIR"/points/*/; do
  k=$(basename "$p"); l="${k%-c*}"
  cp "$BENCH_DIR/launches/$l/server.log" "$p/server.log" 2>/dev/null || true
done
OUT="${RESULT_DIR:-$INFMAX_CONTAINER_WORKSPACE/results}/bench"
mkdir -p "$OUT" && cp -r "$BENCH_DIR/points" "$BENCH_DIR/launches" "$BENCH_DIR/status.json" "$BENCH_DIR/patch-info.txt" "$OUT/"
raw=$(ls "$BENCH_DIR"/points/*/raw/agg.json 2>/dev/null | head -1)
[ -n "$raw" ] && cp "$raw" "$INFMAX_CONTAINER_WORKSPACE/$RESULT_FILENAME.json"
exit $rc
